#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define STACK_MAX 64

static long stack[STACK_MAX];
static int top = 0; // number of elements on the stack

static void error(void) {
    puts("ERROR");
    exit(0); // original binary exits after printing ERROR
}

static void push(long v) {
    if (top >= STACK_MAX) error();
    stack[top++] = v;
}

static long pop(void) {
    if (top == 0) error();
    return stack[--top];
}

static int parse_number(const char *tok, long *out) {
    char *endptr;
    errno = 0;
    long v = strtol(tok, &endptr, 10);
    if (errno != 0 || *endptr != '\0') return 0;
    *out = v;
    return 1;
}

static void apply_operator(char op) {
    long right = pop(); // first popped = right operand
    long left  = pop(); // second popped = left operand
    long res;
    switch (op) {
        case '+': res = left + right; break;
        case '-': res = left - right; break;
        case '*': res = left * right; break;
        case '/':
            if (right == 0) error();
            res = left / right;
            break;
        default: error();
    }
    push(res);
}

int main(int argc, char **argv) {
    if (argc < 2) error(); // need at least one token

    for (int i = 1; i < argc; ++i) {
        const char *tok = argv[i];
        // operator: single char among + - * /
        if (strlen(tok) == 1 && strchr("+-*/", tok[0]) != NULL) {
            apply_operator(tok[0]);
            continue;
        }
        // otherwise must be a number
        long val;
        if (!parse_number(tok, &val)) error();
        push(val);
    }

    if (top != 1) error(); // after processing exactly one value must remain
    printf("%ld\n", stack[0]);
    return 0;
}
